/**
 * Generates src/contract.gen.ts, the TypeScript types of an LLMClient's architecture, the tree of the SAM resources that it is built from, from
 * contract/llmclient-architecture.schema.json.
 *
 * The schema is generated by the Smarter backend, from the contract's Pydantic models
 * (smarter.apps.prompt.views.detailviews.architecture_contract), and copied here by `make llmclient-architecture-contract`.
 * src/contract.test.ts fails if src/contract.gen.ts is out of date. See scripts/contract-types.mjs in the workspace.
 *
 *     npm run contract:types                    # writes src/contract.gen.ts
 *     node scripts/contract-types.mjs --check   # exits 1 if src/contract.gen.ts is out of date
 */
import path from "node:path";

import { runContractTypes } from "../../../scripts/contract-types.mjs";

await runContractTypes({
  root: path.resolve(import.meta.dirname, ".."),
  schemaFile: "llmclient-architecture.schema.json",
  typeName: "LLMClientArchitectureContract",
  title: "The LLMClient architecture's contract",
});
